    // and the review card in the sheet JSX is the only thing that calls
    // handleSave for a voice entry — same manual confirmation a typed
    // entry always required, just pre-filled instead of pre-saved.

    async function handleDelete(id) {
      // Sept 9 2026, Jimmy: keep the row's array position too, not just the
      // row itself — restoring it later needs to land back exactly where it
      // was, not at the bottom of the list under other exercises.
      const idx = entries.findIndex((x) => x.id === id);
      const target = idx !== -1 ? entries[idx] : null;
      setEntries((prev) => prev.filter((x) => x.id !== id));
      clearTimeout(undoTimer.current);
      function scheduleUndo() {
        if (!target) return;
        setLastDeleted({ entry: target, index: idx });
        undoTimer.current = setTimeout(() => setLastDeleted(null), 6000);
      }
      if (!sb) { scheduleUndo(); return; }
      const { error: err } = await sb.from("workout_entries").delete().eq("id", id);
      if (err) {
        // Delete failed server-side — put the row back in its original spot
        // rather than leaving the screen showing a delete that didn't happen.
        if (target) setEntries((prev) => { const next = [...prev]; next.splice(Math.min(idx, next.length), 0, target); return next; });
        setError("Couldn't delete that — try again.");
        return;
      }
      scheduleUndo();
    }

    // Sept 12 2026, Jimmy: "can we make the workout exercise look to look
    // like this" — deletes one SET out of an entry (not the whole entry),
    // matching the design-audit mockup's per-row delete. Guards against
    // removing the last set, since an entry with zero sets doesn't make
    // sense here — deleting the last one should go through the whole-entry
    // delete above instead (the row's own delete button is disabled then).
    async function handleDeleteSet(entryId, setIdx) {
      const idx = entries.findIndex((x) => x.id === entryId);
      if (idx === -1) return;
      const target = entries[idx];
      if (!target.sets || target.sets.length <= 1) return;
      const newSets = target.sets.filter((_, i) => i !== setIdx);
      setEntries((prev) => prev.map((x) => (x.id === entryId ? { ...x, sets: newSets } : x)));
      if (!sb) return;
      const { error: err } = await sb.from("workout_entries").update({ sets: newSets }).eq("id", entryId);
      if (err) {
        setEntries((prev) => prev.map((x) => (x.id === entryId ? { ...x, sets: target.sets } : x)));
        setError("Couldn't delete that set — try again.");
      }
    }

    async function handleUndoDelete() {
      const pending = lastDeleted;
      if (!pending) return;
      const { entry, index } = pending;
      clearTimeout(undoTimer.current);
      setLastDeleted(null);
      if (!sb) return;
      const payload = { date: entry.date, exercise: entry.exercise, muscle_group: entry.muscleGroup, workout_title: entry.workoutTitle || null, sets: entry.sets, client_name: clientName, client_id: clientId || null };
      const { data, error: err } = await sb.from("workout_entries").insert([payload]).select();
      if (err || !data) {
        setError("Couldn't undo that delete — try again.");
        return;
      }
      const row = data[0];
      const mapped = { id: row.id, date: row.date, exercise: row.exercise, muscleGroup: row.muscle_group, sets: row.sets, workoutTitle: row.workout_title, clientName: row.client_name, createdAt: row.created_at };
      // Sept 9 2026, Jimmy: "i want when i undo to see the exercise where it
      // was, not below other exercises" — reinsert at the same array spot it
      // was removed from (clamped, in case the list shrank further since)
      // instead of appending to the end, so it reappears exactly where it
      // was within its day/session card rather than jumping to the bottom.
      setEntries((prev) => { const next = [...prev]; next.splice(Math.min(index, next.length), 0, mapped); return next; });
    }
    function dismissUndo() { clearTimeout(undoTimer.current); setLastDeleted(null); }

    // Sept 9 2026, Jimmy: bulk-moves every exercise sharing one session's
    // date+title to a new date and/or title in one action, instead of
    // opening each exercise's own edit form and retyping both by hand.
    async function handleEditSession(oldDate, oldTitle, newDate, newTitle) {
      const finalDate = newDate || oldDate;
      const finalTitle = (newTitle || "").trim();
      if (finalDate === oldDate && finalTitle === (oldTitle || "")) return;
      const matchIds = entries.filter((x) => x.date === oldDate && (x.workoutTitle || "") === (oldTitle || "")).map((x) => x.id);
      if (!matchIds.length) return;
      setEntries((prev) => prev.map((x) => (matchIds.includes(x.id) ? { ...x, date: finalDate, workoutTitle: finalTitle || null } : x)));
      if (!sb) return;
      const { error: err } = await sb.from("workout_entries").update({ date: finalDate, workout_title: finalTitle || null }).in("id", matchIds);
      if (err) {
        // Revert every row this touched back to its old date/title on failure —
        // same "don't leave the screen showing an unsaved change" rule as the
        // rest of the app's optimistic updates.
        setEntries((prev) => prev.map((x) => (matchIds.includes(x.id) ? { ...x, date: oldDate, workoutTitle: oldTitle || null } : x)));
        setError("Couldn't update that session — try again.");
      }
    }
    // Sept 18 2026, Jimmy: "delete button also for the title beside the
    // upper body for example" — same bulk match-by-date+title as
    // handleEditSession above, but removes every matching row instead of
    // updating them. No optimistic-then-revert here since ConfirmDialog
    // already gates it (see confirmDeleteSession in LogFeed) — waits for
    // the real result before updating the screen either way.
    async function handleDeleteSession(date, title) {
      const matchIds = entries.filter((x) => x.date === date && (x.workoutTitle || "") === (title || "")).map((x) => x.id);
      if (!matchIds.length) return;
      if (!sb) { setEntries((prev) => prev.filter((x) => !matchIds.includes(x.id))); return; }
      const { error: err } = await sb.from("workout_entries").delete().in("id", matchIds);
      if (err) {
        setError("Couldn't delete that session — try again.");
        return;
      }
      setEntries((prev) => prev.filter((x) => !matchIds.includes(x.id)));
    }

