  // Shows (and, for a trainer/manager, lets you set) the ONE program a specific client is
  // actually following right now — distinct from the full template library in ProgramsPanel,
  // which every trainer can browse and build from. Assigning here is what turns a shared
  // template into "this is Sarah's program."
  // Sept 10 2026, Jimmy: a self-train client's own "request a program" affordance
  // (the Assign button + picker below) only ever lived up in "Your program," well
  // above the fold once someone's scrolled down into "Browse all programs" — each
  // locked card down there just said "pick it above" as plain, non-clickable text.
  // forwardRef + quickPick exposes a way for ProgramsPanel's own browse cards to
  // trigger a pick directly (see the "Request this program" button below), reusing
  // this exact same tested assign logic instead of duplicating it.
  const ClientProgramCard = React.forwardRef(function ClientProgramCard({ clientName, clientId, userId = null, userEmail = null, canAssign = false, isSelfTrain = false, gatePayment = false, appAccessOk = true, paidAccessOk = true, trainerId = null, onAssignmentChange = null }, ref) {
    const [loaded, setLoaded] = useState(false);
    const [assignment, setAssignment] = useState(null);
    const [program, setProgram] = useState(null);
    const [exercises, setExercises] = useState([]);
    const [allPrograms, setAllPrograms] = useState([]);
    const [picking, setPicking] = useState(false);
    const [pickedId, setPickedId] = useState("");
    const [saving, setSaving] = useState(false);
    const [error, setError] = useState("");
    // Sept 13 2026, Jimmy: inline "are you sure" instead of window.confirm().
    const [confirmUnassign, setConfirmUnassign] = useState(false);
    // Sept 11 2026: "View full program" on the restyled hero card scrolls
    // down to the existing day-by-day exercise list instead of duplicating it.
    const programDetailRef = useRef(null);
    // Sept 14 2026, Jimmy: which exercise's "Log weight" button was tapped
    // (holds both the exercise row and its day label, for LogProgramWeightModal's
    // context line) — works the same whether this program was bought
    // (self-train, no trainer) or assigned by a trainer, since it's just
    // logging into the client's own workout log either way.
    const [logTarget, setLogTarget] = useState(null);
    // Sept 15 2026, Jimmy: "i want the client to be able to tap on every
    // week like the program the trainer assign so he's doesnt have to
    // scroll all the way down" — same week-chip filter
    // ClientCustomProgramCard already has for a trainer-written program;
    // this card (the shared-catalog "Your program") never had it, so a
    // long multi-week program was one long scroll with no way to jump
    // straight to, say, Week 8. "all" shows every week same as before.
    const [activeWeek, setActiveWeek] = useState("all");
    // Sept 19 2026, walkthrough finding: same one-tap nudge DietPanel
    // already has for a client stuck waiting on their trainer — this card's
    // own "ask your trainer" empty state (below) had no equivalent.
    const [nudgeSent, setNudgeSent] = useState(false);
    function handleNudgeTrainer() {
      if (!trainerId) return;
      notifyTrainer(trainerId, `${clientName || "Your client"} is waiting on a program to be assigned.`);
      setNudgeSent(true);
    }

    useEffect(() => { loadAssignment(); }, [clientName, clientId]);

    // Guards against a dangling week filter (e.g. the program gets
    // reassigned/changed and the previously-selected week label no longer
    // exists), which would otherwise silently show nothing.
    useEffect(() => {
      if (activeWeek !== "all" && !weekGroups().some((w) => w.label === activeWeek)) setActiveWeek("all");
    }, [exercises]);

    async function loadAssignment() {
      // Sept 10 2026: this used to also require clientName truthy — but the
      // actual lookup below keys entirely on clientId, and clientName can be
      // legitimately blank/still-loading for a real client. Requiring it too
      // was silently hiding this whole "request a program" card for anyone
      // it happened to be blank for, with no error and no obvious cause.
      if (!sb || !clientId) { setLoaded(true); return; }
      setLoaded(false);
      const { data: rows } = await sb.from("client_program_assignments").select("*").eq("client_id", clientId).order("assigned_at", { ascending: false }).limit(1);
      const a = rows && rows[0];
      setAssignment(a || null);
      if (onAssignmentChange) onAssignmentChange(a || null);
      if (a) {
        const { data: prog } = await sb.from("training_programs").select("*").eq("id", a.program_id).maybeSingle();
        setProgram(prog || null);
        if (prog) {
          const { data: exRows } = await sb.from("program_exercises").select("*").eq("program_id", prog.id).order("order_index", { ascending: true });
          setExercises(exRows || []);
        } else {
          setExercises([]);
        }
      } else {
        setProgram(null);
        setExercises([]);
      }
      setLoaded(true);
    }

    async function openPicker() {
      // Belt-and-suspenders — the button that calls this is hidden while
      // purchaseLocked, but guard here too in case anything else ever calls it.
      if (purchaseLocked) return;
      setPicking(true);
      setError("");
      setPickedId("");
      if (sb) {
        const { data } = await sb.from("training_programs").select("id, name, style").order("style", { ascending: true }).order("order_index", { ascending: true });
        const list = data || [];
        setAllPrograms(list);
        // A native <select> with no matching option for value="" still visually
        // shows the first option in the list — but our state stays empty until
        // the user actually changes it, so clicking Assign without touching the
        // dropdown looked like it did nothing. Default the picked id to whatever
        // is actually shown so Assign works immediately.
        if (list.length > 0) setPickedId(list[0].id);
      }
    }

    // Sept 10 2026: accepts an explicit programId so a "Request this program"
    // button elsewhere (ProgramsPanel's own browse cards, via the quickPick
    // ref below) can trigger the exact same assign flow directly on one
    // specific card, instead of only ever working through the picker
    // dropdown's own pickedId state. The picker's Assign button still calls
    // this with no argument, which falls back to pickedId exactly as before.
    // Returns true/false so a caller (ProgramsPanel's browse-list "Choose
    // this program" button, via quickPick below) can tell whether a pick
    // actually went through, instead of assuming it always did.
    async function handleAssign(explicitId) {
      const id = explicitId || pickedId;
      if (!id) { setError("Pick a program."); return false; }
      // Sept 18 2026, Jimmy retest: the picker's own "Assign" button and
      // openPicker() both already check purchaseLocked before letting
      // anyone get this far, but the browse-list "Choose this program"
      // button (ProgramsPanel -> handleRequestProgram -> quickPick) called
      // straight into this function with no check at all — a self-train
      // client whose trial AND payment had both lapsed could still request
      // a brand-new program. Same belt-and-suspenders guard as openPicker.
      //
      // Sept 18 2026 retest round 2: this can also be hit by a client still
      // inside their free trial who just hasn't paid the app-access fee
      // yet (purchaseLocked is about payment, not trial expiry) — "lapsed"
      // wrongly implied something that used to work had broken.
      if (purchaseLocked) { setError("Pay to unlock picking a program."); return false; }
      if (!sb) { setError("Backend not configured yet."); return false; }
      setSaving(true);
      setError("");
      if (assignment) await sb.from("client_program_assignments").delete().eq("id", assignment.id);
      const payload = { client_name: clientName, client_id: clientId, program_id: id };
      // Self-train clients only need to pay once per program — if
      // client_payments already has a row for this exact client + program_id
      // (even from an assignment that's since been deleted, e.g. they
      // removed it and are picking it back), this pick comes back already
      // unlocked instead of re-gating something they've genuinely already
      // paid for. Checked by isSelfTrain (a real client property), not
      // gatePayment (which is only true in the client's own view — the
      // manager's assign screen always passes gatePayment=false but still
      // needs this same check when reassigning a self-train client's
      // program). Trainer-owned clients are untouched — paid never gates
      // them either way.
      //
      // Matched by userId (client_payments.user_id, the same real key every
      // payment row is written against everywhere else in this file) —
      // NOT client_name. Two different clients can share the same display
      // name, and matching on the name alone would either wrongly grant one
      // of them free access off the other's payment, or wrongly block a
      // legitimate re-charge after a client renames themselves. If userId
      // isn't available for some reason, this safely skips the check rather
      // than querying on a name — worst case a client is asked to pay again,
      // never wrongly granted free access.
      if (isSelfTrain && userId) {
        const { data: priorPayment } = await sb.from("client_payments").select("id").eq("user_id", userId).eq("program_id", id).limit(1).maybeSingle();
        if (priorPayment) payload.paid = true;
      }
      const { error: err } = await sb.from("client_program_assignments").insert([payload]);
      setSaving(false);
      if (err) { setError("Couldn't assign that program. Try again."); return false; }
      // Notify the client only once this pick is actually usable — a
      // trainer-attached client is never payment-gated, so an assignment IS
      // the unlock; a self-train client only counts as unlocked here if they
      // already had a prior payment for this exact program (payload.paid,
      // set above). If they haven't paid, ProgramRequestRow.handleUnlock is
      // the thing that notifies them once that payment is marked received —
      // notifying here too would tell them it's "ready" before it actually is.
      if (userId && (!isSelfTrain || payload.paid)) {
        const pickedProgram = allPrograms.find((p) => p.id === id);
        notifyClient(userId, `Your program${pickedProgram ? ` "${pickedProgram.name}"` : ""} is ready — check your Programs tab.`);
      }
      setPicking(false);
      setPickedId("");
      // Awaited (not fire-and-forget) so a caller using quickPick via ref —
      // ProgramsPanel's "Request this program" button — can rely on this
      // resolving only once assignment state (and onAssignmentChange) is
      // actually up to date, not just once the insert itself finished.
      await loadAssignment();
      if (onAssignmentChange) onAssignmentChange();
      return true;
    }

    async function handleUnassign() {
      if (!assignment || !sb) return;
      setConfirmUnassign(false);
      setSaving(true);
      await sb.from("client_program_assignments").delete().eq("id", assignment.id);
      setSaving(false);
      loadAssignment();
      if (onAssignmentChange) onAssignmentChange();
    }

    // Sept 15 2026: groups by week_label first, then day_label within it —
    // a plain dayGroups() (day_label only) used to silently MERGE two
    // different weeks' exercises together whenever they reused the same day
    // label (e.g. every week's "Day 1 — Squat"), which is exactly what a
    // duplicated week would do. week_label missing (an older row, or a
    // program with only one week) reads as "Week 1".
    function weekGroups() {
      const byWeek = {};
      const order = [];
      exercises.forEach((r) => {
        const wl = r.week_label || "Week 1";
        if (!byWeek[wl]) { byWeek[wl] = { days: {}, dayOrder: [] }; order.push(wl); }
        const wk = byWeek[wl];
        if (!wk.days[r.day_label]) { wk.days[r.day_label] = []; wk.dayOrder.push(r.day_label); }
        wk.days[r.day_label].push(r);
      });
      return order.map((label) => ({ label, days: byWeek[label].dayOrder.map((d) => ({ label: d, rows: byWeek[label].days[d] })) }));
    }

    // Exposed so ProgramsPanel's own "Request this program" button (on each
    // locked browse card) can trigger a real pick directly, reusing this
    // exact tested handleAssign logic instead of a second copy of it. Called
    // unconditionally, before the loading early-return below, per the rules
    // of hooks.
    React.useImperativeHandle(ref, () => ({ quickPick: (programId) => handleAssign(programId) }));

    if (!loaded) return e("div", { style: styles.empty }, e("p", { style: styles.emptyText }, "Loading program…"));

    // Blocks picking or changing a program at all, before any $35 payment
    // even enters the picture — Jimmy's call (Sept 5 2026): a self-train
    // client must already have this month's $10 app access marked PAID
    // (not just be inside the free trial) before they're allowed to buy a
    // program. Never true for a manager or a trainer-attached client.
    const purchaseLocked = gatePayment && !paidAccessOk;
    const pendingPayment = gatePayment && !(assignment && assignment.paid);
    // The $35 unlocks this program once, but a self-train client's monthly
    // $10 is what keeps it viewable — same rule as Log/Diet. If they've paid
    // for the program but their app access has lapsed, the program re-locks
    // too, and comes back as soon as they're paid up again (no re-buying the
    // program). appAccessOk is always true for managers and trainer-attached
    // clients, so this never affects them.
    const subscriptionLocked = gatePayment && !pendingPayment && !appAccessOk;
    const contentLocked = pendingPayment || subscriptionLocked;

    // Shown instead of the program card's own content whenever picking is
    // true — for BOTH "has a program, tapped Change" and "no program yet,
    // tapped Assign a program". Previously this form only ever rendered
    // appended after the current program's full exercise list, which for a
    // multi-day circuit program could be 30+ rows down — easy to tap
    // "Change" and see nothing happen without scrolling a long way. Putting
    // it right where the program's own content normally sits means it's
    // visible immediately, no scrolling required.
    const pickerForm = e("div", { style: { ...styles.sessionForm, marginTop: program ? 0 : 14 } },
      e("label", { style: styles.formLabel }, "Choose a program"),
      allPrograms.length === 0
        ? e("p", { style: styles.emptyText }, "No programs exist yet — build one in the Programs tab first.")
        : e(Select, { value: pickedId, onChange: setPickedId, options: allPrograms.map((p) => ({ value: p.id, label: `${styleLabel(p.style)} — ${p.name}` })), style: { width: "100%" } }),
      e("div", { style: { display: "flex", gap: 8, marginTop: 12 } },
        // Sept 18 2026 retest round 2: this was `onClick: handleAssign`,
        // which hands handleAssign the raw click SyntheticEvent as its
        // `explicitId` argument (React always passes the event to a
        // directly-referenced handler). Since that event object is truthy,
        // `explicitId || pickedId` picked the EVENT over the actual
        // dropdown selection every time — the insert then failed (an event
        // object isn't a program id) and "Assign" from this picker form
        // could never actually succeed, always landing on the generic
        // "Couldn't assign that program" error. Wrapping in an arrow so no
        // argument is passed and it correctly falls back to pickedId.
        e("button", { style: { ...styles.saveBtn, marginTop: 0, flex: 1, ...(saving ? styles.btnDisabled : {}) }, disabled: saving || allPrograms.length === 0, onClick: () => handleAssign() }, saving ? "Assigning…" : "Assign"),
        e("button", { style: { ...styles.demoLinkBtn, padding: "0 10px" }, onClick: () => { setPicking(false); setPickedId(""); setError(""); } }, "Cancel")
      )
    );

    const allWeekGroups = weekGroups();
    const groupsToShow = activeWeek === "all" ? allWeekGroups : allWeekGroups.filter((w) => w.label === activeWeek);

    return e("div", null,
      error && e("div", { style: { ...styles.errorBanner, margin: "0 0 12px" } }, e(Icon, { name: "x", size: 13, color: C.critical }), error),
      program
        ? e("div", {
            style: {
              ...styles.programCard, position: "relative", overflow: "hidden",
              // Sept 11 2026, Jimmy: brand-ring "current plan" treatment,
              // matching the reference mockup — only once it's actually
              // live (not mid-pick, not still locked behind payment).
              ...(!contentLocked && !picking ? { boxShadow: `inset 0 0 0 1.5px ${C.brand}, ${C.cardShadow}` } : {})
            }
          },
            e("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 8 } },
              e("div", { style: styles.programHeader },
                e("div", { style: { display: "flex", alignItems: "center", gap: 10 } },
                  !contentLocked && !picking && e("div", { style: styles.planHeroIconWrap }, e(Icon, { name: "dumbbell", size: 16, color: C.brand })),
                  e("div", null,
                    e("span", { style: styles.demoNote }, styleLabel(program.style)),
                    e("span", { style: { ...styles.sectionTitle, display: "block", marginTop: 2 } }, program.name)
                  )
                ),
                // Picking a program (even before paying) used to reveal its
                // full description here immediately — same leak as the
                // browse list, just one screen later. Clamp it the same way
                // while payment/access is locked; it opens up full-width the
                // moment contentLocked clears.
                !picking && program.description && e("p", {
                  style: contentLocked
                    ? { ...styles.profileGoalText, marginTop: 4, display: "-webkit-box", WebkitLineClamp: 3, WebkitBoxOrient: "vertical", overflow: "hidden" }
                    : { ...styles.profileGoalText, marginTop: 4 }
                }, program.description)
              ),
              e("div", { style: { display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 8, flexShrink: 0 } },
                !contentLocked && !picking && e("span", { style: styles.currentBadge }, e(Icon, { name: "check", size: 9, color: C.brandInk }), "CURRENT"),
                canAssign && !picking && e("div", { style: { display: "flex", gap: 8, alignItems: "center" } },
                  // Switching to a different program is a new pick — same
                  // paid-access-required rule as picking one the first time —
                  // so "Change" is hidden while purchaseLocked. Removing the
                  // current pick (trash) stays available either way; it's not
                  // a purchase.
                  !purchaseLocked && e("button", { style: styles.demoLinkBtn, onClick: openPicker }, "Change"),
                  e("button", { style: styles.deleteBtn, onClick: () => setConfirmUnassign(true), "aria-label": "Unassign program" }, e(Icon, { name: "trash", size: 14 }))
                )
              )
            ),
            confirmUnassign && e("div", { style: { ...styles.deleteConfirmBar, flexDirection: "column", alignItems: "stretch", gap: 8, marginTop: 10 } },
              e("span", { style: styles.deleteConfirmText },
                isSelfTrain
                  ? `Remove this program? ${gatePayment ? "You'll" : "They'll"} lose access to it. Picking it again later won't ask for payment again, but a different one will.`
                  : "Remove this program? They'll lose access to it until it's assigned again."
              ),
              e("div", { style: { display: "flex", gap: 8 } },
                e("button", { style: { ...styles.confirmCancelBtn, flex: 1 }, onClick: () => setConfirmUnassign(false) }, "Cancel"),
                e("button", { style: { ...styles.confirmDangerBtn, flex: 1 }, onClick: handleUnassign }, "Remove")
              )
            ),
            !contentLocked && !picking && allWeekGroups.length > 0 && e("button", {
              style: { ...styles.ghostPillBtn, marginTop: 12 },
              onClick: () => programDetailRef.current && programDetailRef.current.scrollIntoView({ behavior: "smooth", block: "start" })
            }, "View full program", e(Icon, { name: "chevron", size: 13, color: C.ink, strokeWidth: 2.4 })),
            picking
              ? e("div", { style: { marginTop: 16 } }, pickerForm)
              : (pendingPayment
                  ? e("div", { style: { ...styles.empty, marginTop: 16, flexDirection: "column", alignItems: "center", gap: 8 } },
                      e(Icon, { name: "lock", size: 20, color: C.ink3 }), e("p", { style: styles.emptyText }, "Pay below to unlock this program."),
                      // Same real stepper as the app-access lock screens — the
                      // client can mark "I've sent the payment" and then see
                      // "Under review" right here instead of a static line
                      // with no way to tell it went anywhere. Context is keyed
                      // per program (program.id), separate from the app-access
                      // claim below, since a client can owe both at once.
                      e(PaymentStatusStepper, { email: userEmail, context: `program_${program.id}`, amount: PROGRAM_PRICE, approvedCopy: "Approved — unlocked" })
                    )
                  : subscriptionLocked
                  ? e("div", { style: { ...styles.empty, marginTop: 16, flexDirection: "column", alignItems: "center", gap: 8 } },
                      e(Icon, { name: "lock", size: 20, color: C.ink3 }), e("p", { style: styles.emptyText }, `Your $${PROGRAM_PRICE} program is on hold — pay this month's $${SELF_TRAIN_MONTHLY_PRICE} app access to see it again.`),
                      // Same claim as the Log/Diet app-access lock screen
                      // (context "self_train_access") — it's the same $/month
                      // payment, so marking it sent on either screen clears
                      // both.
                      e(PaymentStatusStepper, { email: userEmail, context: "self_train_access", amount: SELF_TRAIN_MONTHLY_PRICE, approvedCopy: "Approved — unlocked" })
                    )
                  : e("div", { ref: programDetailRef },
                      // Sept 15 2026, Jimmy: same "press the week and see
                      // the workout" chip row as the trainer-written
                      // program below — jumping to a specific week is one
                      // tap instead of a scroll past every week before it.
                      allWeekGroups.length > 1 && e("div", { style: { display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 16 } },
                        [{ label: "all", text: "All weeks" }, ...allWeekGroups.map((w) => ({ label: w.label, text: w.label }))].map((opt) => {
                          const active = activeWeek === opt.label;
                          return e("button", {
                            key: opt.label, type: "button", onClick: () => setActiveWeek(opt.label),
                            style: {
                              display: "inline-flex", alignItems: "center", background: active ? C.brandSoft : "transparent",
                              color: active ? C.brand : C.ink3, border: `1px solid ${active ? withAlpha(C.brand, 0.4) : C.cardBorder}`,
                              borderRadius: 20, padding: "6px 12px", fontFamily: "'Inter', sans-serif", fontSize: 12.5, fontWeight: 700,
                              cursor: "pointer", whiteSpace: "nowrap"
                            }
                          }, opt.text);
                        })
                      ),
                      groupsToShow.map((week) => e("div", { key: week.label, style: { marginTop: 16 } },
                        e("div", { style: { ...styles.sectionTitle, fontSize: 13.5 } }, week.label),
                        week.days.map((day) => e("div", { key: day.label, style: { marginTop: 10, marginLeft: 8 } },
                          e("div", { style: styles.dayHead }, day.label),
                          e("div", { style: { display: "flex", flexDirection: "column", gap: 8, marginTop: 8 } },
                            day.rows.map((ex) => e(ProgramExerciseRow, { key: ex.id, ex, canManage: false, onEdit: () => {}, onDelete: () => {}, onLogWeight: () => setLogTarget({ ex, contextLabel: `${program.name} — ${week.label} · ${day.label}` }) }))
                          )
                        ))
                      ))
                    )
                ),
            !contentLocked && !picking && e(ProgramWatermark, { label: clientName }),
            logTarget && e(LogProgramWeightModal, {
              ex: logTarget.ex, clientId, clientName, contextLabel: logTarget.contextLabel,
              onClose: () => setLogTarget(null)
            })
          )
        : e("div", { style: styles.empty }, e(ProgramsEmptyArt, {}), e("p", { style: { ...styles.emptyText, ...(!canAssign && !isSelfTrain && !nudgeSent ? { marginBottom: 8 } : {}) } },
            canAssign
              ? (purchaseLocked
                  // Sept 13 2026, Jimmy: "to be clear that the $10 is
                  // subscription before he buys the program" — a
                  // self-train client hits this even mid-free-trial (see
                  // the purchaseLocked rule above: paid access, not just
                  // "in trial", is required before picking a program), so
                  // without this the $10 read as if it were the program's
                  // price. Spelled out as the recurring monthly app
                  // subscription, separate from the program itself.
                  ? `This $${SELF_TRAIN_MONTHLY_PRICE} is your monthly app subscription — not the program itself. It needs to be paid first, even while your free trial is still running, before you can pick a program. Pay below, then come back here.`
                  : gatePayment ? `No program picked yet — browse below, choose one, then pay to unlock it ($${PROGRAM_PRICE}).` : "No program assigned yet.")
              : (isSelfTrain ? "No program assigned yet — pay to unlock the program library." : "No program assigned yet — ask your trainer.")
          ),
          // Sept 19 2026, walkthrough fix: same one-tap nudge DietPanel
          // already has — only for the trainer-attached case (the only one
          // with a real trainer to nudge; isSelfTrain has no trainer,
          // canAssign is a manager viewing a client, not the client itself).
          !canAssign && !isSelfTrain && trainerId && (!nudgeSent
            ? e("button", { type: "button", style: { ...styles.demoLinkBtn, padding: "0" }, onClick: handleNudgeTrainer }, "Nudge my trainer →")
            : nudgeSent && e("p", { style: { ...styles.emptyText, fontSize: 11.5, color: C.good } }, "Nudge sent — your trainer's been notified.")),
          purchaseLocked && e(WhishPayBox, { amount: SELF_TRAIN_MONTHLY_PRICE, note: "which is your monthly app subscription, then wait for JimFit to confirm — programs unlock once you're paid up" })
          ),
      // "Assign a program" reads like manager/trainer language when it's a
      // self-training client picking one for themselves — same button and
      // handler, just a wording swap based on who's looking at it.
      canAssign && !program && !picking && !purchaseLocked && e("button", { style: { ...styles.newBtn, marginTop: 14 }, onClick: openPicker }, e(Icon, { name: "calendar", size: 15 }), isSelfTrain ? "Choose a program" : "Assign a program"),
      canAssign && !program && picking && pickerForm
    );
  });

  // Sept 13 2026, Jimmy: "what if later i want to check for every client the
  // program we are working on" — onProgramChange (optional) tells a caller
  // that keeps its own roster-level summary (TrainerView's clientPrograms
  // map) about a create/rename/delete the instant it happens here, so that
  // list doesn't go stale until the next full page load. Passes null on
  // delete, { title, updatedAt } otherwise — same shape as the roster map.
  // Sept 18 2026, Jimmy: "let a trainer copy one of their own client's
  // existing programs into another client's" — trainers write every
  // client's program from scratch here, and a trainer with several clients
  // on the same split (e.g. Push/Pull/Legs) was retyping the same days/
  // exercises every time. `copyFromOptions` (optional, [{clientId,
  // clientName, title}]) lists this trainer's OTHER clients who already
  // have a program, for a "Copy from another client" alternative to
  // "Write a new program" — see handleCopyFromClient below. Empty/omitted
  // is fully backward compatible (button just doesn't render), so the
  // manager's own call site (CoachView, which doesn't pass this — Jimmy's
  // Sept 5 2026 call was managers use the separate shared library instead)
  // is unaffected.
  function ClientCustomProgramCard({ clientName, clientId, userId = null, canManage = false, onProgramChange, copyFromOptions = [] }) {
    const [loaded, setLoaded] = useState(false);
    const [program, setProgram] = useState(null);
    const [items, setItems] = useState([]);
    const [error, setError] = useState("");

    const [creating, setCreating] = useState(false);
    // "Copy from another client" — picking a source client's most recent
    // program and cloning it (title/description + every week/day/exercise
    // row) into a brand-new program for THIS client. See
    // handleCopyFromClient below.
    const [copyOpen, setCopyOpen] = useState(false);
    const [copySourceId, setCopySourceId] = useState("");
    const [copying, setCopying] = useState(false);
    const [editingTitle, setEditingTitle] = useState(false);
    const [titleForm, setTitleForm] = useState({ title: "", description: "" });
    const [savingTitle, setSavingTitle] = useState(false);
    // Sept 13 2026, Jimmy: inline "are you sure" instead of window.confirm().
    const [confirmDeleteProgram, setConfirmDeleteProgram] = useState(false);
    // Sept 18 2026: the trash icon on a single exercise row used to delete
    // it the instant it was tapped, unlike deleting the whole program (right
    // above) which already asks first. Same ConfirmDialog pattern here too —
    // holds the exercise being confirmed (or null).
    const [confirmDeleteItem, setConfirmDeleteItem] = useState(null);
    const [deletingItem, setDeletingItem] = useState(false);

    const [addTarget, setAddTarget] = useState(null); // { weekLabel, dayLabel } — add exercise to an existing day
    const [newDayFor, setNewDayFor] = useState(null); // weekLabel — add a brand-new day under this week
    const [addingWeek, setAddingWeek] = useState(false); // adding a brand-new week (+ its first day)
    const [editTarget, setEditTarget] = useState(null); // { id } — editing an existing exercise
    // Sept 14 2026, Jimmy: which exercise's "Log weight" button was tapped
    // (holds the exercise row + its week/day context) — for a client's own
    // view of a program a trainer wrote them, same LogProgramWeightModal
    // used for bought/ready programs, so trainer-assigned clients get the
    // exact same weekly weight tracking as self-train clients do.
    const [logTarget, setLogTarget] = useState(null);
    const [form, setForm] = useState(BLANK_CUSTOM_ITEM_FORM);
    const [saving, setSaving] = useState(false);
    // Sept 14 2026, Jimmy: "Save & add another" on the exercise form below —
    // same brief "Added" flash pattern as the workout-log sheets, in place
    // of the form closing to confirm the save happened.
    const savedFlashTimer = useRef(null);
    const [savedFlash, setSavedFlash] = useState(false);
    // Sept 11 2026, Jimmy: "i cant edit the day 1 (copy)!" — a day is just a
    // label shared by every exercise row under it (no separate day record),
    // and there was never any control to change that label at all — most
    // visible right after "Duplicate day" leaves you with a literal
    // "(copy)" suffix stuck in place. { weekLabel, dayLabel } identifies
    // which day's label is being edited right now.
    const [renamingDay, setRenamingDay] = useState(null);
    const [dayNameDraft, setDayNameDraft] = useState("");
    // Sept 11 2026, Jimmy: "i cant press the copy and see the paste" — the
    // duplicate-exercise button worked, but the new row just silently
    // appeared wherever it landed in a long list, so it looked like nothing
    // happened. justDuplicatedId briefly highlights + auto-scrolls to the
    // new row right after it's created, so the "paste" is actually visible.
    const [justDuplicatedId, setJustDuplicatedId] = useState(null);
    const rowRefs = useRef({});
    // Sept 13 2026, Jimmy: "i want the trainer to see only the 3 weeks
    // program the notes and program description and click on it and see
    // whats inside... so if he gave the client more than a program not
    // scroll a lot" — a program with a lot written in it used to render
    // every week/day/exercise at once. Collapsed shows just the title +
    // description (a click expands it); expanded adds a week selector (see
    // activeWeek below) so a specific week is one tap away instead of a
    // long scroll. Starts collapsed; the effect right below auto-expands a
    // brand-new/empty program so "add your first week" isn't hidden.
    const [expanded, setExpanded] = useState(false);
    // "all" shows every week same as before; a specific week label filters
    // the program down to just that week's days/exercises — the "search"
    // Jimmy asked for ("press the week and see the workout").
    const [activeWeek, setActiveWeek] = useState("all");

    useEffect(() => {
      if (!justDuplicatedId) return;
      const node = rowRefs.current[justDuplicatedId];
      if (node && node.scrollIntoView) node.scrollIntoView({ behavior: "smooth", block: "center" });
      const t = setTimeout(() => setJustDuplicatedId(null), 2200);
      return () => clearTimeout(t);
    }, [justDuplicatedId]);

    useEffect(() => { loadProgram(); }, [clientId]);

    async function loadProgram() {
      if (!sb || !clientId) { setLoaded(true); return; }
      setLoaded(false);
      const { data: rows, error: progErr } = await sb.from("client_custom_programs").select("*").eq("client_id", clientId).order("created_at", { ascending: false }).limit(1);
      // Sept 13 2026, Jimmy: "its a bug i guess" — an already-saved program
      // disappeared off the screen entirely after an unrelated save error.
      // This fetch never checked for a Supabase error before, so any
      // transient failure here (network blip, timeout, etc.) silently wiped
      // an existing program from view even though nothing was deleted. Now
      // a failed fetch leaves whatever was already on screen alone and
      // surfaces the real error instead of guessing the program is gone.
      if (progErr) {
        setError(`Couldn't load this program (${progErr.message}). Try again.`);
        setLoaded(true);
        return;
      }
      const p = rows && rows[0];
      setProgram(p || null);
      if (p) {
        const { data: itemRows, error: itemsErr } = await sb.from("client_program_items").select("*").eq("program_id", p.id).order("order_index", { ascending: true });
        if (itemsErr) {
          setError(`Couldn't load this program's exercises (${itemsErr.message}). Try again.`);
        } else {
          setItems(itemRows || []);
        }
      } else {
        setItems([]);
      }
      setLoaded(true);
    }

    function weekGroups() {
      const byWeek = {};
      const order = [];
      items.forEach((r) => {
        if (!byWeek[r.week_label]) { byWeek[r.week_label] = { days: {}, dayOrder: [] }; order.push(r.week_label); }
        const wk = byWeek[r.week_label];
        if (!wk.days[r.day_label]) { wk.days[r.day_label] = []; wk.dayOrder.push(r.day_label); }
        wk.days[r.day_label].push(r);
      });
      return order.map((label) => ({ label, days: byWeek[label].dayOrder.map((d) => ({ label: d, rows: byWeek[label].days[d] })) }));
    }

    // A program with nothing written in it yet auto-expands so "add your
    // first week" is immediately visible instead of hidden behind a click —
    // collapsed-by-default only makes sense once there's something to hide.
    useEffect(() => {
      if (loaded && program && weekGroups().length === 0) setExpanded(true);
    }, [loaded, program, items]);

    // Guards against a dangling week filter — e.g. the last exercise under
    // the currently-selected week gets deleted and that week label no
    // longer exists — which would otherwise silently show nothing.
    useEffect(() => {
      if (activeWeek !== "all" && !weekGroups().some((w) => w.label === activeWeek)) setActiveWeek("all");
    }, [items]);

    async function handleCreateProgram() {
      if (!titleForm.title.trim()) { setError("Enter a program title."); return; }
      if (!sb || !clientId) { setError("Backend not configured yet."); return; }
      setError(""); setSavingTitle(true);
      const payload = { client_id: clientId, client_name: clientName, title: titleForm.title.trim(), description: titleForm.description.trim() || null };
      const { data, error: err } = await sb.from("client_custom_programs").insert([payload]).select().maybeSingle();
      setSavingTitle(false);
      if (err || !data) { setError(`Couldn't create that program. Try again.${err && err.message ? ` (${err.message})` : ""}`); return; }
      setProgram(data);
      setItems([]);
      setCreating(false);
      setTitleForm({ title: "", description: "" });
      // Sept 18 2026, Jimmy: "when a trainer assign a program for client the
      // client can see a notification" — the library-assign flow
      // (ClientProgramCard's handleAssign) already did this; writing a
      // custom program from scratch for a client here did not. canManage
      // true means a trainer/owner is the one writing this (the client's
      // own read-only view passes canManage: false), so this never notifies
      // someone about their own action.
      if (canManage && userId) notifyClient(userId, `Your trainer started a new custom program for you${data.title ? ` — "${data.title}"` : ""} — check your Programs tab.`);
      if (onProgramChange) onProgramChange({ title: data.title, updatedAt: data.updated_at || data.created_at });
    }

    // Clones another one of this trainer's clients' most recent program —
    // title, description, and every week/day/exercise row — into a brand
    // new program for THIS client, so a trainer putting the same split on
    // several clients doesn't have to retype it every time. Only offered
    // when this client has no program yet (same as "Write a new program",
    // right next to it) — same reasoning as handleCreateProgram: no
    // "replace" flow exists here, so a client who already has a program
    // has to delete it first (the existing Delete program control) before
    // either option reappears.
    //
    // Deliberately does NOT copy the `weight` column on each exercise row
    // — that's the actual weight the SOURCE client logged/was set to lift,
    // which is meaningless (and could read as a real prescribed number) on
    // a different client's copy. Everything else about the exercise
    // (sets/reps/rest/notes) carries over so the trainer only has to
    // adjust what's actually different for this client.
    async function handleCopyFromClient(sourceClientId) {
      if (!sb || !clientId || !sourceClientId) return;
      setError("");
      setCopying(true);
      const { data: srcProgRows, error: progErr } = await sb.from("client_custom_programs").select("*").eq("client_id", sourceClientId).order("created_at", { ascending: false }).limit(1);
      if (progErr || !srcProgRows || !srcProgRows[0]) {
        setError(`Couldn't load that client's program. Try again.${progErr && progErr.message ? ` (${progErr.message})` : ""}`);
        setCopying(false);
        return;
      }
      const srcProgram = srcProgRows[0];
      const { data: srcItems, error: itemsErr } = await sb.from("client_program_items").select("*").eq("program_id", srcProgram.id).order("order_index", { ascending: true });
      if (itemsErr) {
        setError(`Couldn't load that program's exercises. Try again.${itemsErr.message ? ` (${itemsErr.message})` : ""}`);
        setCopying(false);
        return;
      }
      const payload = { client_id: clientId, client_name: clientName, title: srcProgram.title, description: srcProgram.description || null };
      const { data: newProgram, error: createErr } = await sb.from("client_custom_programs").insert([payload]).select().maybeSingle();
      if (createErr || !newProgram) {
        setError(`Couldn't create the copied program. Try again.${createErr && createErr.message ? ` (${createErr.message})` : ""}`);
        setCopying(false);
        return;
      }
      setProgram(newProgram);
      let newItems = [];
      if (srcItems && srcItems.length) {
        const itemPayload = srcItems.map((it) => ({
          program_id: newProgram.id, client_name: clientName,
          week_label: it.week_label, day_label: it.day_label, exercise: it.exercise,
          // Sept 18 2026 QA catch: the legacy top-level `weight` summary
          // column is correctly left off this payload (defaults to null),
          // but `sets_detail` — the real per-set data this form actually
          // reads/writes (summarizeSetsDetail's comment: "always the
          // source of truth") — embeds each set's own `weight`, e.g.
          // `{reps, weight, rest}`. Copying that wholesale would have
          // leaked the SOURCE client's actual per-set weights into the
          // new client's program as if prescribed, exactly what the
          // "don't copy weight between clients" intent was trying to
          // avoid. Every other field on each set (reps/duration/rest/
          // isTimed/isBodyweight) still carries over — only weight is
          // stripped, kept at 0 for a bodyweight set (never personalized
          // anyway) and null otherwise.
          sets_detail: it.sets_detail ? it.sets_detail.map((s) => ({ ...s, weight: s.isBodyweight ? 0 : null })) : null,
          sets: it.sets, reps: it.reps, rest_seconds: it.rest_seconds, notes: it.notes,
          order_index: it.order_index
        }));
        const { data: newItemRows, error: itemsInsertErr } = await sb.from("client_program_items").insert(itemPayload).select();
        if (itemsInsertErr) {
          setError("Program copied, but copying its exercises failed. You can add them manually.");
        } else {
          newItems = newItemRows || [];
        }
      }
      setItems(newItems);
      setCopying(false);
      setCopyOpen(false);
      setCopySourceId("");
      setExpanded(true);
      if (canManage && userId) notifyClient(userId, `Your trainer started a new custom program for you${newProgram.title ? ` — "${newProgram.title}"` : ""} — check your Programs tab.`);
      if (onProgramChange) onProgramChange({ title: newProgram.title, updatedAt: newProgram.updated_at || newProgram.created_at });
    }

    async function handleSaveTitle() {
      if (!titleForm.title.trim()) { setError("Enter a program title."); return; }
      if (!sb || !program) return;
      setError(""); setSavingTitle(true);
      const payload = { title: titleForm.title.trim(), description: titleForm.description.trim() || null, updated_at: new Date().toISOString() };
      const { data, error: err } = await sb.from("client_custom_programs").update(payload).eq("id", program.id).select().maybeSingle();
      setSavingTitle(false);
      if (err || !data) { setError(`Couldn't save those changes. Try again.${err && err.message ? ` (${err.message})` : ""}`); return; }
      setProgram(data);
      setEditingTitle(false);
      if (onProgramChange) onProgramChange({ title: data.title, updatedAt: data.updated_at || data.created_at });
    }

    async function handleDeleteProgram() {
      if (!program || !sb) return;
      setConfirmDeleteProgram(false);
      setSaving(true);
      await sb.from("client_custom_programs").delete().eq("id", program.id);
      setSaving(false);
      setProgram(null);
      setItems([]);
      if (onProgramChange) onProgramChange(null);
    }

    function closeItemForm() {
      setAddTarget(null); setNewDayFor(null); setAddingWeek(false); setEditTarget(null);
      setForm(BLANK_CUSTOM_ITEM_FORM); setError(""); setRenamingDay(null); setSavedFlash(false);
    }

    function openRenameDay(weekLabel, dayLabel) {
      closeItemForm();
      setRenamingDay({ weekLabel, dayLabel });
      setDayNameDraft(dayLabel);
    }

    async function handleRenameDay() {
      if (!renamingDay || !program) return;
      const { weekLabel, dayLabel } = renamingDay;
      const trimmed = dayNameDraft.trim();
      if (!trimmed || trimmed === dayLabel) { setRenamingDay(null); return; }
      // Another day in the SAME week already has this label — merging two
      // days together silently would be surprising, so refuse instead.
      if (items.some((r) => r.week_label === weekLabel && r.day_label === trimmed)) {
        setError(`"${weekLabel}" already has a day called "${trimmed}".`);
        return;
      }
      setError("");
      const prevItems = items;
      setItems((prev) => prev.map((r) => (r.week_label === weekLabel && r.day_label === dayLabel ? { ...r, day_label: trimmed } : r)));
      setRenamingDay(null);
      if (sb) {
        const { error: err } = await sb.from("client_program_items")
          .update({ day_label: trimmed })
          .eq("program_id", program.id).eq("week_label", weekLabel).eq("day_label", dayLabel);
        if (err) { setItems(prevItems); setError("Couldn't rename that day. Try again."); }
      }
    }

    function openAddWeek() {
      closeItemForm();
      setAddingWeek(true);
      setForm({ ...BLANK_CUSTOM_ITEM_FORM, weekLabel: `Week ${weekGroups().length + 1}`, dayLabel: "Day 1" });
      // A newly added week wouldn't show at all if a different single week
      // was still selected in the week filter above.
      setActiveWeek("all");
    }

    function openAddDay(weekLabel) {
      closeItemForm();
      setNewDayFor(weekLabel);
      setForm({ ...BLANK_CUSTOM_ITEM_FORM, weekLabel });
    }

    // Sept 11 2026, Jimmy: "if i want to add an exercise i deleted it i can
    // go back to first row or any row and to add the exercise where i want
    // and under or over an exercise" — a new exercise no longer always lands
    // at the very end of the program. `beforeId` (an existing item's id, or
    // null) says where in the day it should land; a null beforeId still
    // means "append at the end of this day", same as before. Every row from
    // the insertion point on gets renumbered so the whole program's
    // order_index stays a clean, gap-free sequence.
    function openAddToDay(weekLabel, dayLabel, beforeId = null) {
      closeItemForm();
      setAddTarget({ weekLabel, dayLabel, beforeId });
      setForm({ ...BLANK_CUSTOM_ITEM_FORM, weekLabel, dayLabel });
    }

    function openEditItem(it) {
      closeItemForm();
      setEditTarget({ id: it.id });
      if (Array.isArray(it.sets_detail) && it.sets_detail.length) {
        const timed = it.sets_detail.some((s) => s.isTimed);
        const bw = it.sets_detail.some((s) => s.isBodyweight);
        setForm({
          weekLabel: it.week_label, dayLabel: it.day_label, exercise: it.exercise,
          sets: it.sets_detail.map((s) => ({
            reps: String(timed ? (s.duration != null ? s.duration : s.reps) : (s.reps != null ? s.reps : "")),
            weight: s.weight != null ? String(s.weight) : "",
            rest: s.rest != null ? String(s.rest) : ""
          })),
          isTimed: timed, isBodyweight: bw, notes: it.notes || "",
          noWeightLog: !!it.no_weight_log
        });
      } else {
        // Legacy row, saved before this form tracked per-set detail — best
        // effort reconstruction of one row per set from the old aggregate
        // columns so an old exercise still opens and edits cleanly; saving
        // it writes it forward as sets_detail from then on. The old reps/
        // weight columns were already free text like "12x10x10"/"70x70x90"
        // (a different value per set) — split on "x" and line each part up
        // with its set instead of repeating one value across every row.
        const bw = (it.weight || "").trim().toLowerCase() === "bodyweight";
        const count = it.sets || 1;
        const repsParts = String(it.reps || "").split(/x/i).map((s) => s.trim()).filter(Boolean);
        const weightParts = bw ? [] : String(it.weight || "").split(/x/i).map((s) => s.trim()).filter(Boolean);
        setForm({
          weekLabel: it.week_label, dayLabel: it.day_label, exercise: it.exercise,
          sets: Array.from({ length: count }, (_, idx) => ({
            reps: repsParts[idx] || repsParts[0] || "",
            weight: bw ? "" : (weightParts[idx] || weightParts[0] || ""),
            rest: it.rest_seconds != null ? String(it.rest_seconds) : ""
          })),
          isTimed: false, isBodyweight: bw,
          notes: it.notes || "",
          noWeightLog: !!it.no_weight_log
        });
      }
    }

    async function handleDeleteItem(id) {
      setItems((prev) => prev.filter((r) => r.id !== id));
      if (sb) await sb.from("client_program_items").delete().eq("id", id);
    }

    // Kept to the same onDelete(id) contract ProgramExerciseRow already uses
    // everywhere else (it's a shared component with two other call sites) —
    // looks the exercise up locally just to show its name in the confirm.
    function requestDeleteItem(id) {
      const ex = items.find((r) => r.id === id);
      setConfirmDeleteItem(ex || { id });
    }
    async function confirmDeleteItemNow() {
      if (!confirmDeleteItem) return;
      setDeletingItem(true);
      await handleDeleteItem(confirmDeleteItem.id);
      setDeletingItem(false);
      setConfirmDeleteItem(null);
    }

    // Splices a just-inserted row into the local `items` order at `insertAt`
    // and renumbers order_index for everything after it — shared by both
    // "add exercise at this position" and "duplicate lands right after its
    // source" below, instead of always appending at the very end.
    async function insertOrderedItem(newItem, insertAt) {
      const ordered = [...items];
      ordered.splice(insertAt, 0, newItem);
      const renumbered = ordered.map((r, i) => ({ ...r, order_index: i }));
      const oldById = new Map(items.map((r) => [r.id, r.order_index]));
      const changed = renumbered.filter((r) => r.id === newItem.id || oldById.get(r.id) !== r.order_index);
      setItems(renumbered);
      if (sb && changed.length) {
        await Promise.all(changed.map((r) => sb.from("client_program_items").update({ order_index: r.order_index }).eq("id", r.id)));
      }
    }

    // Sept 9 2026, Jimmy: no way to copy an exercise or a whole day without
    // retyping it — the shared TRAINING_STYLES library (ProgramsPanel below)
    // already had exactly this for its own programs; this mirrors that same
    // pattern for a client's own hand-written program. Lands right after the
    // exercise it was copied from (not always at the very end of the whole
    // program) so "tweak the copy" means scrolling zero pixels to find it.
    async function handleDuplicateItem(it) {
      if (!sb || !program) return;
      setError("");
      const payload = {
        program_id: program.id, client_name: clientName,
        week_label: it.week_label, day_label: it.day_label, exercise: it.exercise,
        sets_detail: it.sets_detail || null,
        sets: it.sets, reps: it.reps, rest_seconds: it.rest_seconds, notes: it.notes,
        weight: it.weight, order_index: items.length
      };
      const { data, error: err } = await sb.from("client_program_items").insert([payload]).select();
      if (err || !data) { setError(`Couldn't duplicate that exercise. Try again.${err && err.message ? ` (${err.message})` : ""}`); return; }
      const srcIdx = items.findIndex((r) => r.id === it.id);
      await insertOrderedItem(data[0], srcIdx === -1 ? items.length : srcIdx + 1);
      setJustDuplicatedId(data[0].id);
    }

    // Copies a whole day's exercises into a brand-new day within the SAME
    // week, labeled "<original> (copy)" — same auto-labeling as the shared
    // library's handleDuplicateDay below, so trainer expectations match
    // across both program builders.
    async function handleDuplicateDay(weekLabel, dayLabel) {
      if (!sb || !program) return;
      setError("");
      const dayRows = items.filter((r) => r.week_label === weekLabel && r.day_label === dayLabel);
      if (dayRows.length === 0) return;
      const newLabel = `${dayLabel} (copy)`;
      const payload = dayRows.map((it, i) => ({
        program_id: program.id, client_name: clientName,
        week_label: weekLabel, day_label: newLabel, exercise: it.exercise,
        sets_detail: it.sets_detail || null,
        sets: it.sets, reps: it.reps, rest_seconds: it.rest_seconds, notes: it.notes,
        weight: it.weight, order_index: items.length + i
      }));
      const { data, error: err } = await sb.from("client_program_items").insert(payload).select();
      if (err || !data) { setError("Couldn't duplicate that day. Try again."); return; }
      setItems((prev) => [...prev, ...data]);
    }

    // Sept 8 2026, Jimmy: both the trainer and the client log the weight
    // actually used, per set (e.g. "70x70x90"), from the same chip on the
    // exercise row — there's no separate "target weight" field in the
    // write-a-program form anymore. A trainer/manager (canManage) already
    // has direct write access to this table (same as editing sets/reps
    // above), so their save goes straight through. The client otherwise has
    // no write access to this trainer-written program (canManage is false
    // for her everywhere else here), so her save goes through a narrow
    // SECURITY DEFINER RPC (client_update_program_item_weight) instead of a
    // direct table update, so she can only ever touch the weight column on
    // a row that's genuinely hers — same "narrow RPC, never a blanket write
    // grant" pattern as submit_self_body_info etc.
    async function handleWeightSave(id, value) {
      const prevItem = items.find((r) => r.id === id);
      const prevWeight = prevItem ? prevItem.weight : null;
      setItems((prev) => prev.map((r) => (r.id === id ? { ...r, weight: value || null } : r)));
      if (!sb) return;
      // Sept 14 2026 (app walkthrough): this used to destructure `error` off
      // of `result.error` instead of off `result` itself — so on any
      // SUCCESSFUL save (the normal case, where `result.error` is just
      // `null`) it crashed with "Cannot destructure property 'error' of
      // ... as it is null" before ever reaching the revert-on-failure logic
      // below. Every "+ Log weight" save, trainer/owner or client, threw
      // this way. Destructuring straight off the awaited `{data, error}`
      // response (same shape/pattern as every other Supabase call in this
      // file) fixes both branches.
      const { error: err } = canManage
        ? await sb.from("client_program_items").update({ weight: value || null }).eq("id", id)
        : await sb.rpc("client_update_program_item_weight", { p_item_id: id, p_weight: value || null });
      // Sept 8 2026: revert the chip back to the last real value on a failed
      // save — it used to keep showing the unsaved number even though
      // nothing was actually written.
      if (err) {
        setItems((prev) => prev.map((r) => (r.id === id ? { ...r, weight: prevWeight } : r)));
        setError("Couldn't save that weight — try again.");
      }
    }

    async function handleSaveItem(keepOpen) {
      // Sept 14 2026, Jimmy: "Finish & close" reached from a "Save & add
      // another" state — same lesson as the workout-log fix: a blank
      // exercise means there's nothing new to save, so just close instead
      // of erroring at the person.
      if (!keepOpen && !editTarget && !form.exercise.trim() && !form.notes.trim() && form.sets.every((s) => !String(s.reps).trim() && !String(s.weight).trim() && !String(s.rest).trim())) {
        closeItemForm();
        return;
      }
      if (!form.exercise.trim()) { setError("Enter an exercise name."); return; }
      if (!form.weekLabel.trim()) { setError("Enter a week label."); return; }
      if (!form.dayLabel.trim()) { setError("Enter a day label."); return; }
      if (!sb || !program) { setError("Backend not configured yet."); return; }

      // Same shape/validation as the Log form's own per-set save: timed sets
      // carry `duration` instead of `reps`, bodyweight sets force weight to 0
      // and drop the weight column from the grid entirely.
      const cleanSets = form.sets.map((s) => {
        const rest = s.rest ? Number(s.rest) : null;
        const weight = form.isBodyweight ? 0 : (s.weight === "" ? null : Number(s.weight));
        return form.isTimed
          ? { duration: Number(s.reps), weight, rest, isTimed: true, ...(form.isBodyweight ? { isBodyweight: true } : {}) }
          : { reps: Number(s.reps), weight, rest, ...(form.isBodyweight ? { isBodyweight: true } : {}) };
      }).filter((s) => (form.isTimed ? s.duration > 0 : s.reps > 0));
      if (cleanSets.length === 0) { setError(`Add at least one valid set (${form.isTimed ? "seconds" : "reps"} > 0).`); return; }

      setError(""); setSaving(true);
      const summary = summarizeSetsDetail(cleanSets, form.isTimed, form.isBodyweight);

      if (editTarget) {
        const payload = {
          exercise: form.exercise.trim(),
          sets_detail: cleanSets,
          sets: summary.sets, reps: summary.reps, rest_seconds: summary.rest_seconds, weight: summary.weight,
          notes: form.notes.trim() || null
        };
        const { data, error: err } = await sb.from("client_program_items").update(payload).eq("id", editTarget.id).select();
        setSaving(false);
        if (err || !data) { setError(`Couldn't save those changes. Try again.${err && err.message ? ` (${err.message})` : ""}`); return; }
        setItems((prev) => prev.map((r) => (r.id === editTarget.id ? data[0] : r)));
        closeItemForm();
        return;
      }

      const payload = {
        program_id: program.id, client_name: clientName,
        week_label: form.weekLabel.trim(), day_label: form.dayLabel.trim(), exercise: form.exercise.trim(),
        sets_detail: cleanSets,
        sets: summary.sets, reps: summary.reps, rest_seconds: summary.rest_seconds, weight: summary.weight,
        notes: form.notes.trim() || null,
        order_index: items.length // placeholder — insertOrderedItem below fixes the real position
      };
      const { data, error: err } = await sb.from("client_program_items").insert([payload]).select();
      setSaving(false);
      if (err || !data) { setError(`Couldn't save that exercise. Try again.${err && err.message ? ` (${err.message})` : ""}`); return; }

      const newItem = data[0];
      const beforeId = addTarget && addTarget.beforeId;
      let insertAt = items.length;
      if (beforeId) {
        const idx = items.findIndex((r) => r.id === beforeId);
        if (idx !== -1) insertAt = idx;
      } else if (addTarget) {
        // "+ Add exercise" at the bottom of a day — land right after that
        // day's last existing row, not necessarily the very end of the
        // whole program if other weeks/days come after it.
        insertAt = items.length;
        for (let i = items.length - 1; i >= 0; i--) {
          if (items[i].week_label === addTarget.weekLabel && items[i].day_label === addTarget.dayLabel) { insertAt = i + 1; break; }
        }
      }
      await insertOrderedItem(newItem, insertAt);
      if (keepOpen) {
        // Sept 14 2026, Jimmy: "Save & add another" — keeps the form open
        // for the next exercise, same idea as the workout-log sheets.
        // Whether this save was adding to an existing day, a brand-new day,
        // or a brand-new week, that day now genuinely exists (it just got
        // its first exercise), so every subsequent save in this session
        // targets that same week+day directly.
        const weekLabel = form.weekLabel.trim();
        const dayLabel = form.dayLabel.trim();
        setAddTarget({ weekLabel, dayLabel, beforeId: null });
        setNewDayFor(null);
        setAddingWeek(false);
        setEditTarget(null);
        setForm({ ...BLANK_CUSTOM_ITEM_FORM, weekLabel, dayLabel });
        setError("");
        clearTimeout(savedFlashTimer.current);
        setSavedFlash(true);
        savedFlashTimer.current = setTimeout(() => setSavedFlash(false), 2000);
      } else {
        closeItemForm();
      }
    }

    if (!loaded) return e("div", { style: styles.empty }, e("p", { style: styles.emptyText }, "Loading program…"));

    if (!program) {
      return e("div", null,
        error && e("div", { style: { ...styles.errorBanner, margin: "0 0 12px" } }, e(Icon, { name: "x", size: 13, color: C.critical }), error),
        creating
          ? e("div", { style: { ...styles.sessionForm, marginTop: 0 } },
              e("div", { style: { display: "flex", gap: 8 } },
                e("input", { style: { ...styles.inputEllipsis, flex: 1 }, placeholder: "Program title (e.g. Sarah's 6-Week Cut)", value: titleForm.title, onChange: (ev) => setTitleForm({ ...titleForm, title: ev.target.value }) }),
                e(VoiceMicButton, { title: "Say the program title", onTranscribed: (text) => setTitleForm({ ...titleForm, title: text }) })
              ),
              e("div", { style: { display: "flex", gap: 8, marginTop: 10, alignItems: "flex-start" } },
                e("textarea", { style: { ...styles.input, flex: 1, minHeight: 70, resize: "vertical", fontFamily: "'Inter', sans-serif" }, placeholder: "Description (optional)", value: titleForm.description, onChange: (ev) => setTitleForm({ ...titleForm, description: ev.target.value }) }),
                e(VoiceMicButton, { title: "Say the description", onTranscribed: (text) => setTitleForm({ ...titleForm, description: text }) })
              ),
              e("div", { style: { display: "flex", gap: 8, marginTop: 10 } },
                e("button", { style: { ...styles.saveBtn, marginTop: 0, flex: 1, ...(savingTitle ? styles.btnDisabled : {}) }, disabled: savingTitle, onClick: handleCreateProgram }, savingTitle ? "Creating…" : "Create program"),
                e("button", { style: { ...styles.demoLinkBtn, padding: "0 10px" }, onClick: () => { setCreating(false); setTitleForm({ title: "", description: "" }); setError(""); } }, "Cancel")
              )
            )
          : copyOpen
          ? e("div", { style: { ...styles.sessionForm, marginTop: 0 } },
              e("label", { style: styles.formLabel }, "Copy from"),
              e(Select, {
                value: copySourceId, onChange: setCopySourceId,
                options: copyFromOptions.map((o) => ({ value: o.clientId, label: `${o.clientName} — ${o.title || "Untitled program"}` })),
                style: { width: "100%" }
              }),
              e("div", { style: { display: "flex", gap: 8, marginTop: 10 } },
                e("button", {
                  style: { ...styles.saveBtn, marginTop: 0, flex: 1, ...((copying || !copySourceId) ? styles.btnDisabled : {}) },
                  disabled: copying || !copySourceId,
                  onClick: () => handleCopyFromClient(copySourceId)
                }, copying ? "Copying…" : "Copy program"),
                e("button", { style: { ...styles.demoLinkBtn, padding: "0 10px" }, onClick: () => { setCopyOpen(false); setCopySourceId(""); setError(""); } }, "Cancel")
              )
            )
          : (canManage
              ? e("div", { style: { display: "flex", gap: 8, flexWrap: "wrap" } },
                  e("button", { style: styles.newBtn, onClick: () => { setCreating(true); setTitleForm({ title: "", description: "" }); setError(""); } }, e(Icon, { name: "plus", size: 15, strokeWidth: 3 }), "Write a new program"),
                  // Sept 18 2026, Jimmy: "let a trainer copy one of their own
                  // client's existing programs into another client's" — only
                  // shown when there's actually another client of this
                  // trainer's with a program to copy from.
                  copyFromOptions.length > 0 && e("button", {
                    style: { ...styles.coachTabBtn, padding: "11px 20px", fontSize: 13 },
                    onClick: () => { setCopyOpen(true); setCopySourceId(copyFromOptions[0].clientId); setError(""); }
                  }, e(Icon, { name: "copy", size: 14 }), "Copy from another client")
                )
              : e("div", { style: styles.empty }, e(ProgramsEmptyArt, {}), e("p", { style: styles.emptyText }, "No custom program written for you yet.")))
      );
    }

    const allWeekGroups = weekGroups();
    const groupsToShow = activeWeek === "all" ? allWeekGroups : allWeekGroups.filter((w) => w.label === activeWeek);
    const totalExercises = allWeekGroups.reduce((sum, w) => sum + w.days.reduce((s, d) => s + d.rows.length, 0), 0);

    return e("div", null,
      error && e("div", { style: { ...styles.errorBanner, margin: "0 0 12px" } }, e(Icon, { name: "x", size: 13, color: C.critical }), error),
      e("div", { style: styles.programCard },
        editingTitle
          ? e("div", { style: { ...styles.sessionForm, marginTop: 0, marginBottom: 0 } },
              e("div", { style: { display: "flex", gap: 8 } },
                e("input", { style: { ...styles.input, flex: 1 }, placeholder: "Program title", value: titleForm.title, onChange: (ev) => setTitleForm({ ...titleForm, title: ev.target.value }) }),
                e(VoiceMicButton, { title: "Say the program title", onTranscribed: (text) => setTitleForm({ ...titleForm, title: text }) })
              ),
              e("div", { style: { display: "flex", gap: 8, marginTop: 10, alignItems: "flex-start" } },
                e("textarea", { style: { ...styles.input, flex: 1, minHeight: 70, resize: "vertical", fontFamily: "'Inter', sans-serif" }, placeholder: "Description (optional)", value: titleForm.description, onChange: (ev) => setTitleForm({ ...titleForm, description: ev.target.value }) }),
                e(VoiceMicButton, { title: "Say the description", onTranscribed: (text) => setTitleForm({ ...titleForm, description: text }) })
              ),
              e("div", { style: { display: "flex", gap: 8, marginTop: 10 } },
                e("button", { style: { ...styles.saveBtn, marginTop: 0, flex: 1, ...(savingTitle ? styles.btnDisabled : {}) }, disabled: savingTitle, onClick: handleSaveTitle }, savingTitle ? "Saving…" : "Save"),
                e("button", { style: { ...styles.demoLinkBtn, padding: "0 10px" }, onClick: () => { setEditingTitle(false); setError(""); } }, "Cancel")
              )
            )
          : e("div", {
              style: { display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 8, cursor: "pointer" },
              // Sept 13 2026, Jimmy: "click on it and see whats inside" —
              // tapping the header itself (title/description) toggles the
              // program open, same as the explicit chevron button, so
              // there isn't a tiny precise target to hit.
              onClick: () => setExpanded((v) => !v)
            },
              e("div", { style: styles.programHeader },
                e("span", { style: styles.sectionTitle }, program.title),
                program.description && e("p", { style: { ...styles.profileGoalText, marginTop: 4 } }, program.description),
                // Sept 13 2026, Jimmy: "so if he gave the client more than a
                // program not scroll a lot" — collapsed state shows a
                // one-line count instead of every week/day/exercise, so
                // opening a client with a lot written for them doesn't mean
                // scrolling past all of it just to see the title.
                !expanded && allWeekGroups.length > 0 && e("p", { style: { ...styles.muscleSubText, marginTop: 6 } },
                  `${allWeekGroups.length} week${allWeekGroups.length === 1 ? "" : "s"} · ${totalExercises} exercise${totalExercises === 1 ? "" : "s"}`
                )
              ),
              e("div", { style: { display: "flex", gap: 2, flexShrink: 0, alignItems: "center" } },
                canManage && e("button", {
                  style: styles.editBtn, "aria-label": "Edit program",
                  onClick: (ev) => { ev.stopPropagation(); setEditingTitle(true); setTitleForm({ title: program.title, description: program.description || "" }); setError(""); }
                }, e(Icon, { name: "edit", size: 14 })),
                canManage && e("button", { style: styles.deleteBtn, onClick: (ev) => { ev.stopPropagation(); setConfirmDeleteProgram(true); }, "aria-label": "Delete program" }, e(Icon, { name: "trash", size: 15 })),
                e("button", {
                  style: { ...styles.editBtn, transform: expanded ? "rotate(180deg)" : "none" },
                  "aria-label": expanded ? "Collapse program" : "Expand program",
                  title: expanded ? "Hide program details" : "View program",
                  onClick: (ev) => { ev.stopPropagation(); setExpanded((v) => !v); }
                }, e(Icon, { name: "chevron", size: 16 }))
              )
            ),
        confirmDeleteProgram && e("div", { style: { ...styles.deleteConfirmBar, flexDirection: "column", alignItems: "stretch", gap: 8 } },
          e("span", { style: styles.deleteConfirmText }, `Delete "${program.title}"? This removes the whole program and every week/day in it.`),
          e("div", { style: { display: "flex", gap: 8 } },
            e("button", { style: { ...styles.confirmCancelBtn, flex: 1 }, onClick: () => setConfirmDeleteProgram(false) }, "Cancel"),
            e("button", { style: { ...styles.confirmDangerBtn, flex: 1, ...(saving ? styles.btnDisabled : {}) }, disabled: saving, onClick: handleDeleteProgram }, saving ? "…" : "Delete")
          )
        ),
        // Sept 18 2026: the trash icon on a single exercise row (inside
        // day.rows.map below) used to delete it instantly — this is the
        // confirm step, same ConfirmDialog every other "are you sure" in
        // the app that isn't this specific inline-bar style already uses.
        confirmDeleteItem && e(ConfirmDialog, {
          title: "Delete this exercise?",
          message: `This removes "${confirmDeleteItem.exercise || "this exercise"}" from the program. This can't be undone.`,
          confirmLabel: "Delete exercise",
          busy: deletingItem,
          onCancel: () => setConfirmDeleteItem(null),
          onConfirm: confirmDeleteItemNow
        }),
        expanded && allWeekGroups.length === 0 && e("p", { style: { ...styles.emptyText, marginTop: 16 } }, canManage ? "No weeks yet — add the first one below." : "No weeks added yet."),
        // Sept 13 2026, Jimmy: "a search button when he click and open to
        // see the program so if he wants to search lets say week 2 or 5 he
        // doesnt need to scroll all the way down he can press the week and
        // see the workout" — a row of week chips; picking one filters the
        // program down to just that week (groupsToShow above), so jumping
        // to "Week 5" is one tap instead of a scroll past everything before it.
        expanded && allWeekGroups.length > 1 && e("div", { style: { display: "flex", gap: 6, flexWrap: "wrap", marginTop: 16 } },
          [{ label: "all", text: "All weeks" }, ...allWeekGroups.map((w) => ({ label: w.label, text: w.label }))].map((opt) => {
            const active = activeWeek === opt.label;
            return e("button", {
              key: opt.label, type: "button", onClick: () => setActiveWeek(opt.label),
              style: {
                display: "inline-flex", alignItems: "center", background: active ? C.brandSoft : "transparent",
                color: active ? C.brand : C.ink3, border: `1px solid ${active ? withAlpha(C.brand, 0.4) : C.cardBorder}`,
                borderRadius: 20, padding: "6px 12px", fontFamily: "'Inter', sans-serif", fontSize: 12.5, fontWeight: 700,
                cursor: "pointer", whiteSpace: "nowrap"
              }
            }, opt.text);
          })
        ),
        expanded && groupsToShow.map((week) => e("div", { key: week.label, style: { marginTop: 20 } },
          e("div", { style: { ...styles.sectionTitle, fontSize: 14 } }, week.label),
          week.days.map((day) => e("div", { key: day.label, style: { marginTop: 12, marginLeft: 10 } },
            e("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8 } },
              // Sept 11 2026, Jimmy: "i cant edit the day 1 (copy)!" —
              // there was never any way to rename a day at all, most
              // obvious right after "Duplicate day" leaves a literal
              // "(copy)" suffix. Tapping the new pencil icon swaps the
              // label for an inline text field, right where the label
              // itself sits.
              (renamingDay && renamingDay.weekLabel === week.label && renamingDay.dayLabel === day.label)
                ? e("input", {
                    autoFocus: true, value: dayNameDraft, onChange: (ev) => setDayNameDraft(ev.target.value),
                    onBlur: handleRenameDay,
                    onKeyDown: (ev) => { if (ev.key === "Enter") handleRenameDay(); if (ev.key === "Escape") setRenamingDay(null); },
                    style: { ...styles.input, flex: 1, padding: "5px 9px", fontSize: 12.5 }
                  })
                : e("div", { style: styles.dayHead }, day.label),
              canManage && e("div", { style: { display: "flex", gap: 2, flexShrink: 0 } },
                !(renamingDay && renamingDay.weekLabel === week.label && renamingDay.dayLabel === day.label) && e("button", { style: styles.editBtn, onClick: () => openRenameDay(week.label, day.label), "aria-label": "Rename day", title: "Rename this day" }, e(Icon, { name: "edit", size: 13 })),
                e("button", { style: styles.editBtn, onClick: () => handleDuplicateDay(week.label, day.label), "aria-label": "Duplicate day", title: "Duplicate this day within the same week" }, e(Icon, { name: "copy", size: 13 }))
              )
            ),
            e("div", { style: { display: "flex", flexDirection: "column", gap: 8, marginTop: 8 } },
              day.rows.map((ex) => {
                // Sept 11 2026, Jimmy: "add an exercise where i want and
                // under or over an exercise" — a slim "insert here" control
                // above every row (including the first) means a new
                // exercise can land at the top, the bottom, or anywhere
                // between two existing ones, not just appended at the end.
                const insertingHere = canManage && addTarget && addTarget.weekLabel === week.label && addTarget.dayLabel === day.label && addTarget.beforeId === ex.id;
                const editingHere = editTarget && editTarget.id === ex.id;
                return e(React.Fragment, { key: ex.id },
                  canManage && !insertingHere && !editingHere && e("button", {
                    style: styles.insertRowBtn, onClick: () => openAddToDay(week.label, day.label, ex.id),
                    "aria-label": `Add an exercise above ${ex.exercise}`, title: "Insert an exercise here"
                  }, e(Icon, { name: "plus", size: 10, strokeWidth: 3 }), "Insert exercise here"),
                  insertingHere
                    ? e(ProgramSetsForm, { values: form, onChange: setForm, onSave: handleSaveItem, onCancel: closeItemForm, saving, showWeekField: false, showDayField: false, savedFlash })
                    : editingHere
                    ? e(ProgramSetsForm, { values: form, onChange: setForm, onSave: handleSaveItem, onCancel: closeItemForm, saving, showWeekField: false, showDayField: false, saveLabel: "Save changes", contextLabel: `Editing under ${week.label} · ${day.label}` })
                    : e(ProgramExerciseRow, {
                        ex, canManage, onEdit: openEditItem, onDelete: requestDeleteItem, onDuplicate: handleDuplicateItem, canEditWeight: true, onWeightSave: handleWeightSave,
                        // Sept 14 2026, Jimmy: testing this from the Owner's
                        // edit view of a client's program (where he was
                        // looking right at these rows' pencil/copy/trash
                        // icons) asked "where do i log the weight" — this
                        // button was client-view-only at first, on the
                        // theory that only the client logs their own lifts.
                        // Available to the trainer/manager here too now, so
                        // whoever's actually looking at the screen (a
                        // trainer logging what a client did during a
                        // supervised session included) can log it — writes
                        // to this client's log either way, never the
                        // logged-in trainer's own.
                        onLogWeight: () => setLogTarget({ ex, contextLabel: `${program.title} — ${week.label} · ${day.label}` }),
                        justDuplicated: justDuplicatedId === ex.id,
                        rowRef: (node) => { if (node) rowRefs.current[ex.id] = node; else delete rowRefs.current[ex.id]; }
                      })
                );
              })
            ),
            canManage && (
              addTarget && addTarget.weekLabel === week.label && addTarget.dayLabel === day.label && !addTarget.beforeId
                ? e(ProgramSetsForm, { values: form, onChange: setForm, onSave: handleSaveItem, onCancel: closeItemForm, saving, showWeekField: false, showDayField: false, savedFlash })
                : e("button", { style: styles.demoLinkBtn, onClick: () => openAddToDay(week.label, day.label) }, "+ Add exercise")
            )
          )),
          canManage && e("div", { style: { marginTop: 12, marginLeft: 10 } },
            newDayFor === week.label
              ? e(ProgramSetsForm, { values: form, onChange: setForm, onSave: handleSaveItem, onCancel: closeItemForm, saving, showWeekField: false, showDayField: true, saveLabel: "Add day", savedFlash })
              : e("button", { style: styles.demoLinkBtn, onClick: () => openAddDay(week.label) }, "+ Add a day to this week")
          )
        )),
        expanded && canManage && e("div", { style: { marginTop: 20 } },
          addingWeek
            ? e(ProgramSetsForm, { values: form, onChange: setForm, onSave: handleSaveItem, onCancel: closeItemForm, saving, showWeekField: true, showDayField: true, saveLabel: "Add week", savedFlash })
            : e("button", { style: styles.newBtn, onClick: openAddWeek }, e(Icon, { name: "plus", size: 15, strokeWidth: 3 }), "Add a week")
        ),
        logTarget && e(LogProgramWeightModal, {
          ex: logTarget.ex, clientId, clientName, contextLabel: logTarget.contextLabel,
          onClose: () => setLogTarget(null)
        })
      )
    );
  }

export { CLIENT_TAB_KEY, CLIENT_DIET_SUBTAB_KEY, CLIENT_PROGRESS_SUBTAB_KEY, CLIENT_PROGRAMS_SUBTAB_KEY, ClientInjuriesPanel, ClientPicker, ClientLogPanel, CLIENT_DETAIL_SECTIONS, CLIENT_GYM_CODE_KEY, ClientRosterList, ClientsBillingPanel, ClientProgramCard, ClientCustomProgramCard };
